B.bkI=new A.eN("agr-03",B.mB,"Agradecer pela paci\xeancia","Muito obrigado pela sua paci\xeancia e compreens\xe3o enquanto resolv\xedamos tudo para voc\xea.","Thank you very much for your patience and understanding while we sorted everything out for you.","Muchas gracias por tu paciencia y comprensi\xf3n mientras resolv\xedamos todo para ti.",B.cl4)
B.cdT=A.a(s(["indica\xe7\xe3o","recomenda\xe7\xe3o","parceiro"]),t.s)
