B.cDS=A.a(s(["parceria","fechamento","projeto","prazer"]),t.s)
B.bki=new A.eN("agr-06",B.mB,"Agradecer pela parceria ao encerrar projeto","Foi um prazer trabalhar com voc\xea neste projeto! Conte com a gente sempre que surgir uma nova ideia.","It was a pleasure working with you on this project! Count on us whenever a new idea comes up.","\xa1Fue un placer trabajar contigo en este proyecto! Cuenta con nosotros siempre que surja una nueva idea.",B.cDS)
B.cHH=A.a(s(["retorno","r\xe1pido","resposta","agilidade"]),t.s)
B.bkd=new A.eN("agr-07",B.mB,"Agradecer pelo retorno r\xe1pido","Obrigado pelo retorno t\xe3o r\xe1pido! Com essas informa\xe7\xf5es j\xe1 consigo adiantar tudo por aqui.","Thank you for the quick reply! With this information I can move everything forward right away.","\xa1Gracias por responder tan r\xe1pido! Con esta informaci\xf3n ya puedo adelantar todo por aqu\xed.",B.cHH)
B.chp=A.a(s(["cliente fiel","recorrente","volta","novamente"]),t.s)
B.bkF=new A.eN("agr-08",B.mB,"Agradecer cliente que voltou a comprar","Que bom te ver de volta! Muito obrigado por escolher nosso trabalho mais uma vez.","So glad to have you back! Thank you very much for choosing our work once again.","\xa1Qu\xe9 bueno verte de nuevo! Muchas gracias por elegir nuestro trabajo una vez m\xe1s.",B.chp)
